llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Meptazinol, a phenolic opioid analgesic with a tertiary amine, has an absolute oral bioavailability of only 8.7 ± 1.6% in healthy male volunteers after oral dosing, well below the 20% threshold; its high transfer score and shared phenol/amine opioid features support low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, a benzomorphan opioid with a free phenol and tertiary amine, has a mean absolute oral bioavailability of about 18% in healthy subjects, below the 20% threshold; this close structural and pharmacological analogue supports low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Naloxegol, a PEGylated morphinan, was simulated to have 90% oral bioavailability, which would support high bioavailability; however, this is a PBPK simulation of a PEG-modified derivative and is outweighed by direct human low-F data from closer phenolic opioids.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Codeine, a related morphinan, has high oral bioavailability (80.5%) in healthy subjects, but it is the 3-methyl ether lacking the free phenolic group that drives first-pass conjugation in the query; this high-F evidence is therefore less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxymorphone, a phenolic morphinan opioid. The most transferable direct human evidence comes from meptazinol (F ~8.7%) and pentazocine (F ~18%), both below 20%, reflecting extensive first-pass metabolism of phenolic opioids. Contradictory high-F analogues are either PEGylated/simulated (naloxegol) or lack the free phenol (codeine), so they do not override the low-F prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule in the provided evidence.",
    "Naloxegol high-F evidence is from a PBPK simulation rather than an experimental human study.",
    "Codeine high-F evidence is from a 3-methylated analogue, limiting transferability to the free-phenol query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

